import ast
import sys
import types
import traceback


def _api(tree):
    # public top-level names -> parameter list; class methods keyed as Class.method
    api = {}
    imports = set()
    for node in tree.body:
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            for a in node.names:
                imports.add(ast.unparse(node) if isinstance(node, ast.ImportFrom) else "import " + a.name)
        elif isinstance(node, ast.FunctionDef) and not node.name.startswith("_"):
            api[node.name] = _params(node)
        elif isinstance(node, ast.ClassDef) and not node.name.startswith("_"):
            api[node.name] = "class"
            for sub in node.body:
                if isinstance(sub, ast.FunctionDef) and not sub.name.startswith("_") or (
                    isinstance(sub, ast.FunctionDef) and sub.name == "__init__"
                ):
                    api[node.name + "." + sub.name] = _params(sub)
    return api, imports


def _params(fn):
    a = fn.args
    names = [x.arg for x in a.posonlyargs + a.args]
    defaults = [ast.unparse(d) for d in a.defaults]
    kwonly = [x.arg for x in a.kwonlyargs]
    star = a.vararg.arg if a.vararg else None
    kw = a.kwarg.arg if a.kwarg else None
    return {"args": names, "defaults": defaults, "kwonly": kwonly, "star": star, "kw": kw}


def _run_tests(module_name, source, tests):
    results = {"passed": [], "failed": [], "error": None}
    mod = types.ModuleType(module_name)
    mod.__file__ = module_name + ".py"
    sys.modules[module_name] = mod
    pyt = types.ModuleType("pytest")

    class _Raises:
        def __init__(self, exc):
            self.exc = exc

        def __enter__(self):
            return self

        def __exit__(self, et, ev, tb):
            if et is None:
                raise AssertionError("DID NOT RAISE " + getattr(self.exc, "__name__", str(self.exc)))
            return issubclass(et, self.exc)

    class _Approx:
        def __init__(self, v):
            self.v = v

        def __eq__(self, other):
            return abs(other - self.v) <= max(1e-6 * abs(self.v), 1e-9)

    pyt.raises = lambda exc, *a, **k: _Raises(exc)
    pyt.approx = lambda v, **k: _Approx(v)
    sys.modules["pytest"] = pyt
    try:
        exec(compile(source, module_name + ".py", "exec"), mod.__dict__)
    except Exception:
        results["error"] = "module import failed: " + traceback.format_exc()[-800:]
        return results
    tmod = types.ModuleType("test_module")
    try:
        exec(compile(tests, "test_module.py", "exec"), tmod.__dict__)
    except Exception:
        results["error"] = "test file failed to load: " + traceback.format_exc()[-800:]
        return results
    for name, fn in list(tmod.__dict__.items()):
        if not (name.startswith("test_") and callable(fn)):
            continue
        try:
            fn()
            results["passed"].append(name)
        except Exception as e:
            frames = [f for f in traceback.extract_tb(e.__traceback__) if f.filename == "test_module.py"]
            where = tests.splitlines()[frames[-1].lineno - 1].strip() if frames else ""
            results["failed"].append(name + ": " + type(e).__name__ + " " + str(e)[:200] + " | failing line: " + where[:300])
    return results


def main(input):
    source = input["source"]
    candidate = input["candidate"]
    tests = input.get("tests") or ""
    module_path = input.get("module_path") or "module.py"
    module_name = module_path.split("/")[-1]
    module_name = module_name[:-3] if module_name.endswith(".py") else module_name
    problems = []
    try:
        cand_tree = ast.parse(candidate)
    except SyntaxError as e:
        return {"ok": False, "compile_error": "SyntaxError line %s: %s" % (e.lineno, e.msg), "problems": ["candidate does not parse"], "passed": [], "failed": [], "test_error": None}
    orig_api, orig_imports = _api(ast.parse(source))
    cand_api, cand_imports = _api(cand_tree)
    for key, sig in orig_api.items():
        if key not in cand_api:
            problems.append("public name removed or renamed: " + key)
        elif sig != "class" and cand_api[key] != sig:
            problems.append("signature changed: " + key)
    for imp in sorted(cand_imports - orig_imports):
        problems.append("new import not in original: " + imp)
    res = _run_tests(module_name, candidate, tests) if tests.strip() else {"passed": [], "failed": [], "error": None}
    ok = not problems and not res["failed"] and not res["error"]
    return {
        "ok": ok,
        "compile_error": None,
        "problems": problems,
        "passed": res["passed"],
        "failed": res["failed"],
        "test_error": res["error"],
    }

