def main(input):
    candidates = [("fix", input["fix"], input["check1"])]
    if input.get("repair") is not None and input.get("check2") is not None:
        candidates.append(("repair", input["repair"], input["check2"]))

    def score(check):
        return len(check["failed"]) + len(check["problems"]) + (1 if check.get("test_error") else 0)

    best = None
    for name, source, check in candidates:
        if check["ok"]:
            best = (source, check)
            break
        if best is None or score(check) <= score(best[1]):
            best = (source, check)
    return {"patched_source": best[0]}
